var wid;
var hei;

var NB_FRAMES;

var frame_count;

function recurDraw(x1,y1,x2,y2,x3,y3,n) {
    if (n<=0) {
        return;
    } else{
        var t = ((frame_count)%NB_FRAMES)/NB_FRAMES;
        stroke(255,255/3*(n-t));
      	var xx1 = (x1+x2)/2;
        var yy1 = (y1+y2)/2;
        var xx2 = (x2+x3)/2;
        var yy2 = (y2+y3)/2;
        var xx3 = (x3+x1)/2;
        var yy3 = (y3+y1)/2;
        line(xx1,yy1,xx2,yy2);
        line(xx3,yy3,xx2,yy2);
        line(xx1,yy1,xx3,yy3);
        recurDraw(x1,y1,xx1,yy1,xx3,yy3,n-1);
        recurDraw(x2,y2,xx1,yy1,xx2,yy2,n-1);
        recurDraw(x3,y3,xx3,yy3,xx2,yy2,n-1);
    }
}

function setup() {

    smooth(16);

  	wid = 500;
    hei = 500;

    NB_FRAMES = 80;

    frame_count = 0;

    createCanvas(wid,hei);

    background(0);
}

function draw() {
    background(0);

    translate(0,50);

    var t = ((frame_count)%NB_FRAMES)/NB_FRAMES;

    stroke(255);

    var rad = 200;

    var offset = PI/6 + 2*PI/3*floor(frame_count/NB_FRAMES);

    var x1 = width/2 + rad*cos(2*PI*0+offset);
    var y1 = height/2 + rad*sin(2*PI*0+offset);
    var x2 = width/2 + rad*cos(2*PI*1/3+offset);
    var y2 = height/2 + rad*sin(2*PI*1/3+offset);
    var x3 = width/2 + rad*cos(2*PI*2/3+offset);
    var y3 = height/2 + rad*sin(2*PI*2/3+offset);

    line(x1,y1,x2,y2);
    line(x2,y2,x3,y3);
    line(x3,y3,x1,y1);

    var interp = lerp(0,0.5,(1-cos(1*PI*t))/2);

    var xx1 = lerp(x1,x2,interp);
    var yy1 = lerp(y1,y2,interp);
    var xx2 = lerp(x2,x3,interp);
    var yy2 = lerp(y2,y3,interp);
    var xx3 = lerp(x3,x1,1-interp);
    var yy3 = lerp(y3,y1,1-interp);
    var xx4 = lerp(x2,x1,interp);
    var yy4 = lerp(y2,y1,interp);

    line(xx3,yy3,xx2,yy2);
    line(xx4,yy4,xx2,yy2);
    line(xx1,yy1,xx3,yy3);

    recurDraw(x1,y1,xx1,yy1,xx3,yy3,5);
    recurDraw(x2,y2,xx4,yy4,xx2,yy2,5);
    recurDraw(x3,y3,xx3,yy3,xx2,yy2,5);

  frame_count++;

}
